'use strict';
/* 픽스처 — 불투명 import(②-c)와 함수 «선언» 모양 생산자(③-b)의 탐지력을 값으로 못박는다.
 * 돌아가지 않는다. 한 파일에 다섯 모양을 섞어 둔다: 세야 하는 셋, 세면 «안 되는» 둘. */

const assert = require('assert');
const { 엔진원문, 모듈세우기, 깨끗이 } = require('./_생산자.js');

const 코드 = 엔진원문();                  // 원문 — 한 겹 건너 온다
const 팩 = 모듈세우기('어떤팩.js');        // 구조 — 파일에서 왔지만 «글»이 아니다
const 정제된 = 깨끗이('어떤파일.js');       // 정제 — 읽고서 감싸 준다

/** ④ 함수 «선언» 모양의 원문 생산자 — 옛 판은 화살표·함수식만 봤다(as 의 `section` 24자리). */
function 구역(시작, 끝) {
  return 코드.slice(코드.indexOf(시작), 코드.indexOf(끝));
}

// ① 세야 한다(위험) — 들여온 생산자가 내준 원문을 «직접» 잰다
assert.ok(!코드.includes('평균'));

// ② 세야 한다(위험) — 함수 «선언» 생산자가 내준 구간도 여전히 파일 원문이다
assert.ok(!구역('function a(', 'function b(').includes('등수'));

// ③ 세야 한다(위험) — 그 파생도 원문이다(`조각 = 코드.slice(…)`)
const 조각 = 코드.slice(0, 100);
assert.ok(!조각.includes('석차'));

// ④ 세야 한다(안전) — 읽고서 «정제해» 준 것은 정제다. 위험으로 세면 이미 감싼 것을
//    또 감싸라는 처방이 된다(F103).
assert.ok(!정제된.includes('평균2'));

// ⑤ 세면 «안 된다»(위험 아님) — 읽었으나 «구조»를 내준 것이다. 모듈 객체는 주석이 사는
//    층이 아니므로 이 축이 원리상 성립하지 않는다. ❔모름으로 «드러내고» 위험으로는 안 센다.
assert.ok(!팩.includes('평균3'));
